#!/usr/bin/env python3
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
CONTACT=set('''POUND KARATE_CHOP DOUBLESLAP COMET_PUNCH MEGA_PUNCH FIRE_PUNCH ICE_PUNCH THUNDERPUNCH SCRATCH VICEGRIP GUILLOTINE CUT WING_ATTACK FLY BIND SLAM VINE_WHIP STOMP DOUBLE_KICK MEGA_KICK JUMP_KICK ROLLING_KICK SAND_ATTACK HEADBUTT HORN_ATTACK FURY_ATTACK HORN_DRILL TACKLE BODY_SLAM WRAP TAKE_DOWN THRASH DOUBLE_EDGE BITE PECK DRILL_PECK SUBMISSION LOW_KICK COUNTER SEISMIC_TOSS STRENGTH DIG QUICK_ATTACK RAGE LICK BIDE CLAMP SKULL_BASH CONSTRICT HI_JUMP_KICK LEECH_LIFE DIZZY_PUNCH CRABHAMMER FURY_SWIPES SLASH STRUGGLE MEGAHORN X_SCISSOR ASTONISH DRAIN_PUNCH STONE_PRESS FLAIL FACADE AERIAL_ACE LUNGE POISON_TAIL POISON_FANG WATERFALL TONGUE_LASH BRICK_BREAK FLAME_CHARGE AQUA_JET AMBUSH SHELL_BREAK TRIPLE_KICK CRUNCH OUTRAGE SHOCK_FANG'''.split())
# Sand Attack is ranged; Counter/Bide are contact retaliation by design.
CONTACT.discard('SAND_ATTACK')
SECONDARY = set("POISON_SIDE_EFFECT1 POISON_SIDE_EFFECT2 BURN_SIDE_EFFECT1 BURN_SIDE_EFFECT2 FREEZE_SIDE_EFFECT PARALYZE_SIDE_EFFECT1 PARALYZE_SIDE_EFFECT2 FLINCH_SIDE_EFFECT1 FLINCH_SIDE_EFFECT2 CONFUSION_SIDE_EFFECT ATTACK_DOWN_SIDE_EFFECT DEFENSE_DOWN_SIDE_EFFECT SPEED_DOWN_SIDE_EFFECT SPECIAL_DOWN_SIDE_EFFECT ATTACK_AND_STAT_EFFECT".split())
SECONDARY_MOVES = {"TRI_ATTACK", "SCALD", "POISON_FANG", "TWINEEDLE"}
SOUND = set("GROWL ROAR SING SUPERSONIC SCREECH WAILING_CRY SNARL HEAL_BELL".split())
PUNCH = set("COMET_PUNCH MEGA_PUNCH FIRE_PUNCH ICE_PUNCH THUNDERPUNCH DIZZY_PUNCH DRAIN_PUNCH".split())
POWDER = {"POISONPOWDER", "STUN_SPORE", "SLEEP_POWDER", "SPORE"}
def render():
 rows=re.findall(r'^\s*move (\w+),\s*(\w+),\s*(\d+),\s*(\w+),\s*(\d+),',(ROOT/'data/moves.asm').read_text(),re.M)
 return '; Generated by tools/generate_ability_moves.py. bit0 damage; bit1 contact; bit2 Flying; bit3 secondary effect; bit4 sound; bit5 powder; bit6 base accuracy 100%; bit7 punch.\nAbilityMoveMetadata:\n'+''.join(f'\tdb {int(int(power)>0)|(2 if name in CONTACT and int(power)>0 else 0)|(4 if typ == "FLYING" else 0)|(8 if int(power)>0 and (effect in SECONDARY or name in SECONDARY_MOVES) else 0)|(16 if name in SOUND else 0)|(32 if name in POWDER else 0)|(64 if int(accuracy)==100 else 0)|(128 if name in PUNCH else 0)} ; {name}\n' for name,effect,power,typ,accuracy in rows)
if __name__=='__main__':(ROOT/'data/ability_move_metadata.asm').write_text(render())
